px}.assignment h3{font-size:13px}.assign-row{display:grid;grid-template-columns:1fr auto;gap:9px;padding:10px 0;border-bottom:1px solid var(--line)}.assign-row small{display:block;color:var(--muted);margin-top:3px}.mono{font-family:'JetBrains Mono'}.switches{display:flex;gap:18px;align-items:center;flex-wrap:wrap;background:var(--bg);border:1px solid var(--line);border-radius:9px;padding:12px}.switches label{display:flex;align-items:center;gap:7px;font-size:12px}.switches input{width:auto}.schedule-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:9px}.schedule{width:100%;border-collapse:collapse;min-width:700px}.schedule th,.schedule td{padding:9px;border-bottom:1px solid var(--line);text-align:left;font-size:11px}.schedule th{color:var(--muted);text-transform:uppercase;letter-spacing:.05em}.schedule input{min-width:115px;padding:8px}.schedule tr:last-child td{border-bottom:0}
