eholder="Mínimo 8 caracteres"></div><div class="field"><label>Estatus del registro</label><select id="f-activo"><option value="1">Activo</option><option value="0">Inactivo</option></select></div></div></div><div class="modal-foot"><span class="message" id="form-msg"></span><button type="button" class="btn" data-close>Cancelar</button><button class="btn primary" type="submit">Guardar</button></div></form></div>
