<script src="assets/js/comun.js?v=20261013-2"></script><script>
const ADMIN=<?= $admin?'true':'false' ?>;let catalog={mosis:[]},selected=null,timer,permissionCatalog=[],permissionSelected=new Set(),initialMosi=new URLSearchParams(location.search).get('id_mosi')||'';const $=id=>document.getElementById(id),val=id=>$(id).value.trim();
const labels={medico:'Médico',psicologo:'Psicólogo',nutriologo:'Nutriólogo'};function initials(p){return ((p.nombre||'?')[0]+((p.apellido||'').trim()[0]||'')).toUpperCase()}function badge(p){return `<span class="badge ${p.estado_operativo}">${p.estado_operativo==='en_consulta'?'En consulta':p.estado_operativo==='disponible'?'Disponible':'Desconectado'}</span>`}
function card(p){const chips=p.mosis.length?p.mosis.slice(0,3).map(m=>`<span class="chip"><b>M</b> ${escapeHtml(m.numero_serie)}</span>`).join(''):'<span class="sub">Sin MOSI asignada</span>';return `<article class="person ${p.tipo_profesional}" data-id="${p.id_personal}" tabindex="0"><div class="person-top"><div class="avatar">${initials(p)}</div><div><h3>${escapeHtml(p.nombre)} ${escapeHtml(p.apellido)}</h3><div class="sub">${labels[p.tipo_profesional]||p.tipo_profesional}${p.especialidad?' · '+escapeHtml(p.especialidad):''}</div></div>${badge(p)}</div><div class="meta"><div class="datum"><small>Sucursal</small><span>${escapeHtml(p.sucursal_legacy)||'Sin sucursal'}</span></div><div class="datum"><small>Turno</small><span>${p.hora_inicio?escapeHtml(String(p.hora_inicio).slice(0,5))+'–'+escapeHtml(String(p.hora_fin||'').slice(0,5)):'No indicado'}</span></div><div class="datum"><small>MOSI</small><span>${p.mosis.length}</span></div><div class="datum"><small>Acceso</small><span>${Number(p.tiene_acceso)?'Tablero activo':'Sin cuenta'}</span></div></div><div class="chips">${chips}${p.mosis.length>3?`<span class="sub">+${p.mosis.length-3}</span>`:''}</div></article>`}
async function load(){const ps=new URLSearchParams({page_size:100});if(val('q'))ps.set('q',val('q'));if(val('tipo'))ps.set('tipo',val('tipo'));if(val('estado'))ps.set('estado',val('estado'));if(val('mosi')||initialMosi)ps.set('id_mosi',val('mosi')||initialMosi);try{const j=await obtenerJSON(`api/personal_clinico.php?${ps}`);catalog=j.catalogos;const cur=$('mosi').value||initialMosi;$('mosi').innerHTML='<option value="">Todas las MOSI</option>'+catalog.mosis.map(m=>`<option value="${m.id_mosi}">${escapeHtml(m.nombre)} · ${escapeHtml(m.numero_serie)}</option>`).join('');$('mosi').value=cur;initialMosi='';const s=j.stats;[['st-total','total'],['st-med','medicos'],['st-psi','psicologos'],['st-nut','nutriologos'],['st-dis','disponibles'],['st-con','en_consulta']].forEach(x=>$(x[0]).textContent=s[x[1]]||0);$('count').textContent=`${j.meta.total} profesional${j.meta.total===1?'':'es'}`;$('list').innerHTML=j.data.length?j.data.map(card).join(''):'<div class="empty">No hay personal que coincida con los filtros.</div>';if($('sync')){$('sync').disabled=!j.legacy_disponible;$('sync').title=j.legacy_disponible?'Importar asignaciones del sistema anterior':'Configura TELEMEDICINA_DB_* o verifica las tablas heredadas';}$('list').querySelectorAll('.person').forEach(e=>{const f=()=>detail(Number(e.dataset.id));e.onclick=f;e.onkeydown=x=>{if(x.key==='Enter'){f()}}});window.mlRenderIcons?.()}catch(e){$('list').innerHTML=`<div class="empty">${escapeHtml(e.message||'No se pudo cargar.')}</div>`}}
async function detail(id){try{const j=await obtenerJSON(`api/personal_clinico.php?id_personal=${id}`);selected=j.data;renderDetail(selected);if($('permissions'))$('permissions').hidden=!selected.id_medico_legacy;open('detail-overlay')}catch(e){mlAlert(e.message)}}function renderDetail(p){const ms=p.mosis.length?p.mosis.map(m=>`<div class="assign-row"><div><strong>${escapeHtml(m.nombre)}</strong><small class="mono">${escapeHtml(m.numero_serie)} · ${escapeHtml(m.grupo_nombre)||'Sin grupo'}</small></div><span class="badge ${m.estado_conexion==='online'?'disponible':'desconectado'}">${m.estado_conexion==='online'?'En línea':'Sin conexión'}</span></div>`).join(''):'<div class="empty" style="padding:20px">Sin módulos MOSI asignados.</div>';const vs=p.vendings.length?p.vendings.map(v=>`<div class="assign-row"><div><strong class="mono">${escapeHtml(v.numero_serie)}</strong><small>${escapeHtml(v.nombre_maquina)||'Vending vinculada'}</small></div><a class="btn" href="maquina.php?id=${v.id_maquina}">Ver</a></div>`).join(''):'<div class="sub">Sin vendings derivadas de sus MOSI.</div>';$('detail').innerHTML=`<div class="detail-hero"><div class="avatar">${initials(p)}</div><div><h2 style="margin:0 0 4px">${escapeHtml(p.nombre)} ${escapeHtml(p.apellido)}</h2><span class="sub">${labels[p.tipo_profesional]}${p.especialidad?' · '+escapeHtml(p.especialidad):''}</span></div>${badge(p)}</div><div class="detail-grid">${[['Cédula',p.cedula_profesional||'No indicada'],['Correo',p.email||'No indicado'],['Teléfono',p.telefono||'No indicado'],['Sucursal origen',p.sucursal_legacy||'Sin sucursal'],['Acceso al panel',Number(p.tiene_acceso)?'Activo':'No configurado'],['Último acceso',p.ultimo_acceso||'Nunca']].map(d=>`<div class="datum"><small>${d[0]}</small><span>${escapeHtml(d[1])}</span></div>`).join('')}</div><section class="assignment"><h3>MOSI asignadas</h3>${ms}</section><section class="assignment"><h3>Vendings relacionadas</h3>${vs}</section>`;window.mlRenderIcons?.()}
function open(id){$(id).classList.add('open')}function close(el){el.closest('.overlay').classList.remove('open')}document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>close(b));document.querySelectorAll('.overlay').forEach(o=>o.onclick=e=>{if(e.target===o)o.classList.remove('open')});
function renderChecks(term='',ids=null){const picked=ids||new Set([...document.querySelectorAll('#checks input:checked')].map(x=>Number(x.value)));const q=term.toLowerCase();const ms=catalog.mosis.filter(m=>`${m.nombre} ${m.numero_serie} ${m.ubicacion||''}`.toLowerCase().includes(q));$('checks').innerHTML=ms.length?ms.map(m=>`<label class="check"><input type="checkbox" value="${m.id_mosi}" ${picked.has(Number(m.id_mosi))?'checked':''}><span><b>${escapeHtml(m.nombre)}</b><small class="mono">${escapeHtml(m.numero_serie)} · ${escapeHtml(m.ubicacion)||'Sin ubicación'}</small></span></label>`).join(''):'<div class="sub">Sin coincidencias.</div>'}
function renderPermissionVendings(term='',ids=null){if(ids)permissionSelected=new Set([...ids].map(String));const q=term.toLowerCase();const rows=permissionCatalog.filter(s=>`${s.st_Nombre} ${s.st_vendingMachine}`.toLowerCase().includes(q));$('p-vendings').innerHTML=rows.length?rows.map(s=>`<label class="check"><input type="checkbox" value="${escapeHtml(s.st_vendingMachine)}" ${permissionSelected.has(String(s.st_vendingMachine))?'checked':''}><span><b>${escapeHtml(s.st_Nombre)}</b><small class="mono">Vending ${escapeHtml(s.st_vendingMachine)}</small></span></label>`).join(''):'<div class="sub">Sin sucursales coincidentes.</div>';$('p-vendings').querySelectorAll('input').forEach(i=>i.onchange=()=>{i.checked?permissionSelected.add(i.value):permissionSelected.delete(i.value)})}
const week=['Lunes','Martes','Miercoles','Jueves','Viernes','Sabado','Domingo'];function renderSchedule(hours={}){$('p-schedule').innerHTML=week.map(d=>{const l=hours[d]?.laboral||{},c=hours[d]?.comida||{};return `<tr data-day="${d}"><td><b>${d==='Miercoles'?'Miércoles':d==='Sabado'?'Sábado':d}</b></td><td><input type="time" data-kind="laboral" data-edge="inicio" value="${escapeHtml(l.inicio||'')}"></td><td><input type="time" data-kind="laboral" data-edge="fin" value="${escapeHtml(l.fin||'')}"></td><td><input type="time" data-kind="comida" data-edge="inicio" value="${escapeHtml(c.inicio||'')}"></td><td><input type="time" data-kind="comida" data-edge="fin" value="${escapeHtml(c.fin||'')}"></td></tr>`}).join('')}
async function openPermissions(){if(!selected?.id_medico_legacy)return;try{$('p-msg').textContent='Cargando…';const j=await obtenerJSON(`api/personal_clinico_permisos.php?id_personal=${selected.id_personal}`);const d=j.data,p=d.permisos||{};permissionCatalog=d.sucursales||[];$('p-id').value=selected.id_personal;$('permissions-person').textContent=`${selected.nombre} ${selected.apellido||''} · ID médico ${selected.id_medico_legacy}`;$('p-device').value=p.st_dispositivo||'ALL';$('p-active').checked=Number(p.i_activo)===1;$('p-consult').checked=Number(p.i_activo_consulta)===1;renderPermissionVendings('',new Set(String(p.st_vendings||'').split(/[,;|\s]+/).filter(Boolean)));renderSchedule(d.horarios||{});$('p-msg').textContent='';$('detail-overlay').classList.remove('open');open('permissions-overlay')}catch(e){$('p-msg').textContent='';mlAlert(e.message||'No se pudieron cargar los permisos.')}}
function form(p=null){$('form').reset();$('f-id').value=p?.id_personal||'';$('form-title').textContent=p?'Editar profesional':'Registrar profesional';$('form-msg').textContent='';if(p){const map={nombre:'f-nombre',apellido:'f-apellido',tipo_profesional:'f-tipo',estado_operativo:'f-estado',especialidad:'f-especialidad',cedula_profesional:'f-cedula',telefono:'f-telefono',email:'f-email',hora_inicio:'f-inicio',hora_fin:'f-fin',activo:'f-activo'};Object.entries(map).forEach(([k,id])=>$(id).value=(p[k]??'').toString().slice(0,id.includes('inicio')||id.includes('fin')?5:999));$('f-acceso').checked=Number(p.tiene_acceso)===1}renderChecks('',new Set((p?.mosis||[]).map(m=>Number(m.id_mosi))));open('form-overlay')}
$('new')?.addEventListener('click',()=>form());$('edit')?.addEventListener('click',()=>{$('detail-overlay').classList.remove('open');form(selected)});$('permissions')?.addEventListener('click',openPermissions);$('find-mosi').oninput=e=>renderChecks(e.target.value);$('p-search')?.addEventListener('input',e=>renderPermissionVendings(e.target.value));$('form').onsubmit=async e=>{e.preventDefault();$('form-msg').textContent='Guardando…';const b={id_personal:val('f-id')||null,nombre:val('f-nombre'),apellido:val('f-apellido'),tipo_profesional:val('f-tipo'),estado_operativo:val('f-estado'),especialidad:val('f-especialidad'),cedula_profesional:val('f-cedula'),telefono:val('f-telefono'),email:val('f-email'),hora_inicio:val('f-inicio'),hora_fin:val('f-fin'),activo:val('f-activo')==='1',crear_acceso:$('f-acceso').checked,password:$('f-password').value,mosis:[...document.querySelectorAll('#checks input:checked')].map(x=>Number(x.value))};try{const r=await fetch('api/personal_clinico_guardar.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});const j=await r.json();if(!j.ok)throw new Error(j.error);$('form-overlay').classList.remove('open');await load()}catch(x){$('form-msg').textContent=x.message||'No se pudo guardar.'}};
$('permissions-form').onsubmit=async e=>{e.preventDefault();$('p-msg').textContent='Guardando en Medical Center…';const horarios={};document.querySelectorAll('#p-schedule tr[data-day]').forEach(tr=>{const day=tr.dataset.day;horarios[day]={laboral:{},comida:{}};tr.querySelectorAll('input[type=time]').forEach(i=>horarios[day][i.dataset.kind][i.dataset.edge]=i.value)});const body={id_personal:Number(val('p-id')),st_dispositivo:val('p-device'),activo:$('p-active').checked,activo_consulta:$('p-consult').checked,vendings:[...permissionSelected],horarios};try{const r=await fetch('api/personal_clinico_permisos.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const j=await r.json();if(!j.ok)throw new Error(j.error);$('permissions-overlay').classList.remove('open');await mlAlert('Permisos y horarios actualizados.','success');await load()}catch(x){$('p-msg').textContent=x.message||'No se pudieron guardar los permisos.'}};
$('sync')?.addEventListener('click',async()=>{if(!await mlConfirm('Se actualizarán médicos, psicólogos y nutriólogos desde las tablas del sistema anterior.','Sincronizar personal','Sincronizar'))return;$('sync').disabled=true;try{const r=await fetch('api/personal_clinico_sincronizar.php',{method:'POST'});const j=await r.json();if(!j.ok)throw new Error(j.error);await mlAlert(`Sincronizados ${j.data.leidos} registros y ${j.data.vinculos_mosi} vínculos con MOSI.`,'success');await load()}catch(e){await mlAlert(e.message||'No se pudo sincronizar.')}finally{$('sync').disabled=false}});
['tipo','estado','mosi'].forEach(id=>$(id).onchange=load);$('q').oninput=()=>{clearTimeout(timer);timer=setTimeout(load,300)};load();
</script></body></html>
